public static int nullSafeHashCode(long[] array) {
    if (array == null) {
        return 0;
    }
    int hashCode = 193;
    for (long element : array) {
        long bits = element;
        hashCode = 29 * hashCode + (int) (bits ^ (bits >>> 32));
    }
    return hashCode;
}

