        throw new NullPointerException ( "The given graph must be non-null" ) ;
    }
    IsomorphicGraphMapping < V , E > automorphism = new IsomorphicGraphMapping < V , E > ( ) ;
    for ( V vertex : graph . vertexSet ( ) ) {
        automorphism . mapVertex ( vertex , vertex ) ;
    }
    for ( E edge : graph . edgeSet ( ) ) {
        automorphism . mapEdge ( edge , edge ) ;
    }
    return automorphism ;
}

