@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Number of vertices in each partition of the complete bipartite graph
    int n1 = 3; // Number of vertices in the first partition
    int n2 = 3; // Number of vertices in the second partition
    int totalVertices = n1 + n2;

    for (int i = 0; i < totalVertices; i++) {
        V vertex = resultMap.get("V" + i);
        target.addVertex(vertex);
    }

    // Add all edges between the partitions
    for (int i = 0; i < n1; i++) {
        for (int j = 0; j < n2; j++) {
            V leftVertex = resultMap.get("V" + i);
            V rightVertex = resultMap.get("V" + (n1 + j));
            target.addEdge(leftVertex, rightVertex);
        }
    }
}

