public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] resolvedClasses = new Class<?>[actualTypeArguments.length];
        for (int i = 0; i < actualTypeArguments.length; i++) {
            resolvedClasses[i] = resolveRawClass(actualTypeArguments[i], targetType);
        }
        return resolvedClasses;
    }
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    if (parameterizedType.getOwnerType() != null && parameterizedType.getOwnerType() != TypeVariableInfo.NONE) {
        Type ownerType = parameterizedType.getOwnerType();
        if (!(ownerType instanceof Class)) {
            return null;
        }
        Class<?> actualType = (Class<?>) ownerType;
        if (!targetType.isAssignableFrom(actualType)) {
            return null;
        }
        Map<TypeVariable<?>, Type> typeMapping = buildTypeVariableMap(targetType);
        Type[] typeArgumentTypes = parameterizedType.getActualTypeArguments();
        Class<?>[] actualTypeArguments = new Class<?>[typeArgumentTypes.length];
        for (int i = 0; i < typeArgumentTypes.length; i++) {
            Type typeArgument = typeArgumentTypes[i];
            Class<?> actualTypeArgument = resolveRawClass(typeArgument, typeMapping);
            if (actualTypeArgument == null) {
                actualTypeArgument = Unknown.class;
            }
            actualTypeArguments[i] = actualTypeArgument;
        }
        return actualTypeArguments;
    }
    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    Type type = parameterizedType.getRawType();
    if (type instanceof Class<?>) {
        Class<?> clazz = (Class<?>) type;
        if (!targetType.isAssignableFrom(clazz)) {
            return null;
        }
        TypeMappingVisitor visitor = new TypeMappingVisitor(targetType);
        visitor.visitTypeMapping(fromClass(clazz), typeVariableMap);
        Type[] typeArgumentTypes = parameterizedType.getActualTypeArguments();
        Class<?>[] actualTypeArguments = new Class<?>[typeArgumentTypes.length];
        for (int i = 0; i < typeArgumentTypes.length; i++) {
            Type typeArgument = typeArgumentTypes[i];
            Class<?> actualTypeArgument = resolveRawClass(typeArgument, typeVariableMap);
            if (actualTypeArgument == null) {
                actualTypeArgument = Unknown.class;
            }
            actualTypeArguments[i] = actualTypeArgument;
        }
        return actualTypeArguments;
    }
    return null;
}

