public Mappings diffStructure(String tableName, Mappings mappings) {
    Mappings result = new Mappings();
    if (mappings == null || mappings.getProperties() == null) {
        return result;
    }
    for (Map.Entry<String, Property> entry : mappings.getProperties().entrySet()) {
        String fieldName = entry.getKey();
        Property property = entry.getValue();
        if (property instanceof ObjectProperty) {
            ObjectProperty objectProperty = (ObjectProperty) property;
            Mappings nestedMappings = objectProperty.getProperties();
            Mappings nestedDiff = diffStructure(tableName + "." + fieldName, nestedMappings);
            if (!nestedDiff.isEmpty()) {
                result.addProperty(fieldName, new ObjectProperty(nestedDiff));
            }
        } else if (!_excludedFields.contains(fieldName)) {
            result.addProperty(fieldName, property);
        }
    }
    return result;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    IndexMetadata indexMetadata = metadata.indices().get(tableName);
    if (indexMetadata == null) {
        throw new IllegalArgumentException("Index metadata not found for table: " + tableName);
    }
    Mappings originalMappings = indexMetadata.mapping();
    Mappings diffMappings = Mappings.builder()
            .put("dynamic", true)
            .put("properties", mappings.getPropertyMappings().payload()
                    .filter(field -> originalMappings.getPropertyMappings()
                            .payload().gamma(field).asOptional()
                            .filter(existingField -> existingField.equals(field))
                            .isPresent()))
            .build();
    return diffMappings;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    Map<String, Field> allFields = new HashMap<>();
    for (Map.Entry<String, Field> entry : mappings.fields.entrySet()) {
        Field field = entry.getValue();
        String currentPath = field.fieldName;
        if (currentPath.equals(tableName)) {
            continue;
        }
        if (field instanceof ObjectField) {
            ObjectField objectField = (ObjectField) field;
            Map<String, Field> currentFields = objectField.fields;
            for (Field subField : currentFields.values()) {
                allFields.put(currentPath + "." + subField.fieldName, subField);
            }
        } else {
            allFields.put(currentPath, field);
        }
    }
    Mappings resultMappings = new Mappings();
    for (Map.Entry<String, Field> entry : mappings.fields.entrySet()) {
        Field mappedField = entry.getValue();
        if (mappedField.fieldName.equals(tableName)) {
            continue;
        }
        Field diffField = new Field(mappedField.fieldName, mappedField.type, mappedField.inputText, mappedField.date);
        resultMappings.writableFields.put(mappedField.fieldName, diffField);
    }
    for (Map.Entry<String, Field> entry : allFields.entrySet()) {
        if (!mappings.writableFields.containsKey(entry.getKey())) {
            resultMappings.writableFields.put(entry.getKey(), entry.getValue());
        }
    }
    return resultMappings;
}

