public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int size = str.length();
    if (size == 0) return lb;
    int bytesNeeded = size * 2;
    while (true) {
        if (bytesNeeded > INT_MAX) {
            throw new IllegalArgumentException("UTF-8-encoded size of string exceeds maximum of 2^31 - 1.");
        }
        LinkedBuffer p = lb.nextBuffer();
        byte[] buf = p.buf;
        int len = p.len;
        if (len > 0) {
            bytesNeeded += len;
        }
        int i = 0;
        int destPos = len;
        while (i < size) {
            if (destPos == buf.length) break;
            char c = str.charAt(i);
            if (c < 0x80) {
                buf[destPos++] = (byte) c;
                i++;
            } else if (c < 0x800) {
                if (destPos + 1 >= buf.length) break;
                buf[destPos++] = (byte) (0xC0 | (c >> 6));
                buf[destPos++] = (byte) (0x80 | (c & 0x3F));
                i++;
            } else if (c < 0xD800 || c > 0xDFFF) {
                if (destPos + 2 >= buf.length) break;
                buf[destPos++] = (byte) (0xE0 | (c >> 12));
                buf[destPos++] = (byte) (0x80 | ((c >> 6) & 0x3F));
                buf[destPos++] = (byte) (0x80 | (c & 0x3F));
                i++;
            } else {
                // surrogate pair
                int idx = i;
                char low = 0;
                if (idx + 1 < size) {
                    low = str.charAt(idx + 1);
                }
                if (c < 0xDC00 && c > 0xD7FF && low >= 0xDC00 && low < 0xE000) {
                    if (destPos + 3 >= buf.length) break;
                    int cp = 0x10000 + (((c - 0xD800) << 10) | (low - 0xDC00));
                    buf[destPos++] = (byte) (0xF0 | (cp >> 18));
                    buf[destPos++] = (byte) (0x80 | ((cp >> 12) & 0x3F));
                    buf[destPos++] = (byte) (0x80 | ((cp >> 6) & 0x3F));
                    buf[destPos++] = (byte) (0x80 | (cp & 0x3F));
                    i += 2;
                } else {
                    if (destPos + 2 >= buf.length) break;
                    buf[destPos++] = (byte) (0xE0 | (c >> 12));
                    buf[destPos++] = (byte) (0x80 | ((c >> 6) & 0x3F));
                    buf[destPos++] = (byte) (0x80 | (c & 0x3F));
                    i++;
                }
            }
        }
        if (i < size) {
            p.len = destPos;
            session.writeSession(lb);
            if (p != lb) {
                lb.release();
            }
            lb = p;
            size -= i;
            i = 0;
        } else {
            p.len = destPos;
            break;
        }
    }
    return lb;
}

