public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }

    int currentBufferOffset = 0;
    final int len = str.length();
    byte[] bytes = new byte[len * 4];
    int byteCount = 0;

    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            bytes[byteCount++] = (byte) c;
        } else if (c <= 0x7FF) {
            bytes[byteCount++] = (byte) (0xC0 | (c >> 6));
            bytes[byteCount++] = (byte) (0x80 | (c & 0x3F));
        } else if (c <= 0xFFFF) {
            bytes[byteCount++] = (byte) (0xE0 | (c >> 12));
            bytes[byteCount++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            bytes[byteCount++] = (byte) (0x80 | (c & 0x3F));
        } else {
            // Surrogate pair handling
            if (i < len - 1 && Character.isHighSurrogate(c)) {
                char low = str.charAt(++i);
                if (Character.isLowSurrogate(low)) {
                    int codePoint = Character.toCodePoint(c, low);
                    bytes[byteCount++] = (byte) (0xF0 | (codePoint >> 18));
                    bytes[byteCount++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
                    bytes[byteCount++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
                    bytes[byteCount++] = (byte) (0x80 | (codePoint & 0x3F));
                } else {
                    // Invalid low surrogate, write as separate char
                    bytes[byteCount++] = (byte) (0xE0 | (c >> 12));
                    bytes[byteCount++] = (byte) (0x80 | ((c >> 6) & 0x3F));
                    bytes[byteCount++] = (byte) (0x80 | (c & 0x3F));
                    bytes[byteCount++] = (byte) 0xE0;
                    bytes[byteCount++] = (byte) (0x80 | (0x7C >> 6));
                    bytes[byteCount++] = (byte) (0x80 | (0x7C & 0x3F));
                }
            } else {
                // Non-BMP char
                bytes[byteCount++] = (byte) (0xE0 | (c >> 12));
                bytes[byteCount++] = (byte) (0x80 | ((c >> 6) & 0x3F));
                bytes[byteCount++] = (byte) (0x80 | (c & 0x3F));
            }
        }
    }

    lb.writeBytes(bytes, 0, byteCount, session);
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int len = str.length();
    BufferedWriter bufferedWriter = new BufferedWriter(session.getWriteChannel());
    try {
        for (int i = 0; i < len; i++) {
            char c = str.charAt(i);
            if (c <= 0x7F) {
                bufferedWriter.write(c);
            } else if (c <= 0x7FF) {
                bufferedWriter.write(0xC0 | ((c >> 6) & 0x1F));
                bufferedWriter.write(0x80 | (c & 0x3F));
            } else if (c <= 0xFFFF) {
                bufferedWriter.write(0xE0 | ((c >> 12) & 0x0F));
                bufferedWriter.write(0x80 | ((c >> 6) & 0x3F));
                bufferedWriter.write(0x80 | (c & 0x3F));
            } else {
                bufferedWriter.write(0xF0 | ((c >> 18) & 0x07));
                bufferedWriter.write(0x80 | ((c >> 12) & 0x3F));
                bufferedWriter.write(0x80 | ((c >> 6) & 0x3F));
                bufferedWriter.write(0x80 | (c & 0x3F));
            }
        }
        bufferedWriter.close();
    } catch (IOException e) {
        throw new RuntimeException("Error writing UTF-8 bytes", e);
    }
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int from = 0;
    int to = str.length();
    int codepointIndex = 0;
    int bufferToIndex = 0;
    while (from < to) {
        int cnum = str.charAt(from);
        if (cnum <= 0) {
            throw new IllegalArgumentException("Invalid char: " + cnum);
        }
        int codepointEndIndex = from + 1;
        int codepoint = cnum;
        if (isSurrogate(cnum)) {
            if (codepointEndIndex >= to) {
                throw new IllegalArgumentException("Unexpected end of string");
            }
            int next = str.charAt(codepointEndIndex);
            if (!isLowSurrogate(next)) {
                throw new IllegalArgumentException("Invalid surrrogate pair");
            }
            codepoint = toCodePoint(cnum, next);
            codepointEndIndex++;
        }
        int firstByteOfCodepoint = bufferToIndex;
        if (isInBmp(codepoint)) {
            lb.putByte((byte) codepoint, bufferToIndex);
            bufferToIndex++;
        } else {
            int secondByteOfCodepoint = bufferToIndex + 1;
            lb.put((short) codepoint, bufferToIndex);
            bufferToIndex += 2;
        }
        from = codepointEndIndex;
    }
    return lb;
}

