public static String findAndSubst(String key, Properties props) {
    if (props == null) {
        throw new IllegalArgumentException("Properties cannot be null");
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Perform variable substitution on the found value
    int maxSubst = Integer.MAX_VALUE;
    int count = 0;
    boolean changed = true;
    while (changed && count < maxSubst) {
        count++;
        StringBuilder sb = new StringBuilder(value);
        int start = sb.indexOf("${");
        if (start < 0) {
            break;
        }
        int end = sb.indexOf("}", start + 2);
        if (end < 0) {
            break;
        }
        String varName = sb.substring(start + 2, end);
        String varValue = props.getProperty(varName);
        if (varValue == null) {
            // If variable not found, leave it as is
            break;
        }
        sb.replace(start, end + 1, varValue);
        value = sb.toString();
        changed = true;
    }
    return value;
}

