public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the midpoint along the X-axis
    double[] x = box.getRangeX();
    double midX = (x[0] + x[1]) / 2.0;

    // Create the left box (from min X to mid X)
    Box2D leftBox = new Box2D(
        x[0], midX, 
        box.getRangeY()[0], box.getRangeY()[1]
    );

    // Create the right box (from mid X to max X)
    Box2D rightBox = new Box2D(
        midX, x[1], 
        box.getRangeY()[0], box.getRangeY()[1]
    );

    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    double center = (box.getMinX() + box.getMaxX()) / 2.0;
    Box2D left = new Box2D(box.getMinX(), center, box.getMinY(), box.getMaxY());
    Box2D right = new Box2D(center, box.getMaxX(), box.getMinY(), box.getMaxY());
    return new Pair<>(left, right);
}

