public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("DataOutput out cannot be null");
    }
    if (node == null) {
        throw new IllegalArgumentException("LinkedBuffer node cannot be null");
    }
    int totalSize = 0;
    byte[] buf;
    while (node != null) {
        buf = node.getBytes();
        totalSize += buf.length;
        out.write(buf);
        node = node.getNext();
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        byte[] buffer = current.getBuffer();
        int size = current.getSize();
        out.write(buffer, 0, size);
        totalSize += size;
        current = current.getNext();
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    for (LinkedBuffer current = node; current != null; current = current.next) {
        out.write(current.data, 0, current.size);
        totalSize += current.size;
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        ByteBuffer buffer = node.getBuffer();
        if (!buffer.hasArray()) {
            // Convert buffer to byte array if it doesn't have a direct array access
            byte[] bytes = new byte[buffer.remaining()];
            buffer.get(bytes);
            out.write(bytes);
            totalSize += bytes.length;
        } else {
            int offset = buffer.arrayOffset() + buffer.position();
            int length = buffer.remaining();
            out.write(buffer.array(), offset, length);
            totalSize += length;
        }
        node = node.next;
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalWritten = 0;
    LinkedBuffer current = node;
    while (current != null) {
        if (current.getBytes() != null && current.getLength() > 0) {
            out.write(current.getBytes(), 0, current.getLength());
            totalWritten += current.getLength();
        }
        current = current.getNext();
    }
    return totalWritten;
}

