}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type.isAssignableFrom(Integer.class)) {
        if (value instanceof Number) {
            return ((Number) value).byteValue();
        } else if (value instanceof String) {
            return Byte.parseByte((String) value);
        } else if (value instanceof Character) {
            return (byte) ((Character) value).charValue();
        }
        throw new UnsupportedOperationException("Unable to convert \"" + value + "\" to a Byte");
    } else if (type.isAssignableFrom(Boolean.class)) {
        if (value instanceof Boolean) {
            return value;
        } else if (value instanceof String) {
            return Boolean.parseBoolean((String) value);
        } else if (value instanceof Number) {
            return ((Number) value).intValue() == 1;
        }
        throw new UnsupportedOperationException("Unable to convert \"" + value + "\" to a Boolean");
    } else if (type.isAssignableFrom(Character.class)) {
        if (value instanceof Character) {
            return value;
        } else if (value instanceof String) {
            String s = (String) value;
            if (s.length() == 1) {
                return s.charAt(0);
            }
        }
        throw new UnsupportedOperationException("Unable to convert \"" + value + "\" to a Character");
    } else if (type.isAssignableFrom(String.class)) {
        return value != null ? value.toString() : null;
    }
    return value;
}

