@Override
    protected Object convertToType(final Class<?> type, final Object value) throws Exception {
        if (type == null) {
            throw new IllegalArgumentException("Type must not be null.");
        }
        if (value == null) {
            return null;
        }
        Class<?> copyableType = getRawType(type);
        if (copyableType == null) {
            throw new IllegalArgumentException("Unsupported type: " + type);
        }
        if (Character.class.isAssignableFrom(copyableType) || char.class.equals(copyableType)) {
            if (value instanceof Character) {
                return value;
            } else if (value instanceof Byte) {
                return (char) (Byte) value;
            } else if (value instanceof Short) {
                return (char) (Short) value;
            } else if (value instanceof Integer) {
                return (char) (Integer) value;
            } else if (value instanceof Character) {
                return value;
            } else if (value instanceof Boolean) {
                return (Boolean) value ? (char) 49 : (char) 48;
            } else if (value instanceof String) {
                String strVal = ((String) value).trim();
                if (strVal.isEmpty()) {
                    return null;
                }
                if (strVal.length() != 1) {
                    throw new IllegalArgumentException("String length cannot be more than one");
                }
                return strVal.charAt(0);
            } else if (Character.class.isAssignableFrom(copyableType)) {
                Object copy = value.get(0);
                return copy;
            } else if (copyableType.isInstance(value)) {
                return value;
            } else {
                try {
                    return copyableType.cast(characterValueOf(value));
                } catch (Exception ex) {
                    throw new IllegalArgumentException(
                        "Unable to convert to [" + copyableType.getName() + " for value [" + value + "]", ex);
                }
            }
        } else if (String.class.isAssignableFrom(copyableType)) {
            if (valueOf(value).length() > 1) {
                throw new IllegalArgumentException("String length cannot be more than one");
            }
            return valueOf(value);
        } else {
            return super.convertToType(type, value);
        }
    }

