public static int nextPrime(int desiredCapacity){
        if (desiredCapacity < MIN_PRIME_CAPACITY) {
            return MIN_PRIME_CAPACITY;
        }
        if (desiredCapacity >= MAXIMUM_HASH_TABLE_SIZE) {
            return null;
        }
        float base = 0;
        int index = (BASE256_DB_SIZE - 1);
        while (index >= 0 && index <= PROBE) {
            index = binarySearch(BASE256_DB, desiredCapacity, index);
            if (index != -1) {
                return index;
            }
            index--;
        }
        return nextPrimeAfter(desiredCapacity);
    }

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("Capacity must be non-negative");
    }    
    if (desiredCapacity < 1000) {
        for (int i = desiredCapacity; i < Integer.MAX_VALUE; i++) {
            if (isPrime(i)) {
                return i;
            }
        }
    } else {
        for (int i = desiredCapacity; i <= desiredCapacity * 1.11; i++) {
            if (isPrime(i)) {
                return i;
            }
        }
    }    
    return Integer.MAX_VALUE;
}

