public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    final int len = str.length();
    if (len == 0) {
        return str;
    }
    final StringBuilder buf = new StringBuilder(len);
    int a = 0;
    for (int i = 0; i < len; i++) {
        final char ch = str.charAt(i);
        if (ch == '\\' && i + 1 < len) {
            final char next = str.charAt(i + 1);
            switch (next) {
                case 'n':
                    buf.append('\n');
                    i++;
                    break;
                case 't':
                    buf.append('\t');
                    i++;
                    break;
                case 'r':
                    buf.append('\r');
                    i++;
                    break;
                case 'f':
                    buf.append('\f');
                    i++;
                    break;
                case 'b':
                    buf.append('\b');
                    i++;
                    break;
                case '\\':
                    buf.append('\\');
                    i++;
                    break;
                case '\'':
                    buf.append('\'');
                    i++;
                    break;
                case '\"':
                    buf.append('\"');
                    i++;
                    break;
                default:
                    buf.append(ch);
                    break;
            }
        } else {
            buf.append(ch);
        }
    }
    return buf.toString();
}

