private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate,Node start,Node stop,int dir){
    OuterFaceCirculator currentCirculator = new OuterFaceCirculator(down(start));
    if (currentCirculator.get().equals(stop)) return currentCirculator;
    if (predicate.test(currentCirculator.get())) {
        // found
        return currentCirculator;
    }
    while (!(currentCirculator.get()).equals(stop)) {
        final OuterFaceCirculator nextCirculator = currentCirculator.next(dir);
        if (predicate.test(nextCirculator.get())) {
            // found
            // TODO: use the last position to return the circulator
            return nextCirculator;
        }
        currentCirculator = nextCirculator;
    }
    // not found
    return currentCirculator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (true) {
        Node node = circulator.node();
        if (predicate.apply(node)) {
            return circulator;
        }
        if (node == stop) {
            break;
        }
        circulator.advance();
        if (node == circulator.node()) {
            break;
        }
    }
    return new OuterFaceCirculator(stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate,Node start,Node stop,int dir){
    OuterFaceCirculator circulator = new OuterFaceCirculator(start,dir);
    if(!predicate.test(circulator.endNode())){
        Node stopNode = stop;
        while(circulator.endNode()!=stopNode){
            circulator.circulate();
        }
    }
    return circulator;
}

