public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength > 0) {
        int loc0 = this.length;
        if (loc0 + byteLength > data.length) {
            enlarge(byteLength);
        }
        byte[] loc1 = this.data;
        if (byteArrayValue != null) {
            System.arraycopy(byteArrayValue, byteOffset, loc1, loc0, byteLength);
        } else {
            java.util.Arrays.fill(loc1, loc0, loc0 + byteLength, (byte) 0);
        }
        this.length = loc0 + byteLength;
    }
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    int loc0 = this.length;
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (loc0 + byteLength > data.length) {
        enlarge(byteLength);
    }
    byte[] loc1 = this.data;
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException();
        }
        System.arraycopy(byteArrayValue, byteOffset, loc1, loc0, byteLength);
    } else {
        for (int i = 0; i < byteLength; i++) {
            loc1[loc0 + i] = 0;
        }
    }
    this.length = loc0 + byteLength;
    return this;
}

