public final MatchResult match(CharSequence uri) {
    if (uri == null) {
        throw new IllegalArgumentException("URI must not be null");
    }
    String uriString = uri.toString();
    if (this.matchPattern == null) {
        return null;
    }
    try {
        Matcher matcher = this.matchPattern.matcher(uriString);
        if (matcher.matches()) {
            Map<String, String> matchedVariables = new HashMap<>();
            List<String> variableNames = this.getVariableNames();
            if (variableNames != null) {
                for (String varName : variableNames) {
                    if (matcher.group(varName) != null) {
                        matchedVariables.put(varName, matcher.group(varName));
                    }
                }
            }
            return new MatchResult(uriString, matchedVariables);
        }
    } catch (Exception e) {
        // If there was an unexpected exception, return null
        return null;
    }
    return null;
}

public final MatchResult match(CharSequence uri) {
    if (uri == null) {
        return null;
    }
    Matcher matcher = this.matchPattern.matcher(uri.toString());
    if (!matcher.matches()) {
        return null;
    }
    // Extract variable values based on the order of variableNames
    Map<String, Object> variables = new LinkedHashMap<>();
    List<String> variableNames = this.variableNames;
    int groupIndex = 1;
    for (int i = 0; i < variableNames.size(); i++) {
        if (groupIndex <= matcher.groupCount()) {
            variables.put(variableNames.get(i), matcher.group(groupIndex));
        }
        groupIndex++;
    }
    return new MatchResult(matcher.group(0), variables, this.uriTemplate);
}

