private void check(String modelName) throws IllegalStateException {
    // Retrieve all sharding key indices for the given model name
    List<Integer> indices = getShardingKeyIndices(modelName);

    // Check if sharding key indices are continuous
    for (int i = 0; i < indices.size() - 1; i++) {
        if (indices.get(i) + 1 != indices.get(i + 1)) {
            throw new IllegalStateException("Sharding key indices are not continuous for model: " + modelName);
        }
    }
}

private void check(String modelName) throws IllegalStateException {
    // Check if the model name is provided
    if (modelName == null || modelName.isEmpty()) {
        throw new IllegalStateException("Model name cannot be null or empty.");
    }

    // Retrieve the list of sharding key indices for the given model
    List<Integer> shardingKeyIndices = _service.getShardingKeyIndices(modelName);

    // Verify that the indices are stored in a map or collection in the expected form
    int lastKey = -1;
    for (int index = 0; index < shardingKeyIndices.size(); index++) {
        int currentKey = shardingKeyIndices.get(index);
        if (currentKey <= lastKey) {
            throw new IllegalStateException(
                "Sharding key indices should be continuous. Last key: " +
                lastKey + ", current key: " + currentKey);
        }
        lastKey = currentKey;
    }
}

