@Override
public Action inspect(AtmosphereResource r) {
    if (r == null) {
        return Action.CONTINUE;
    }

    AtmosphereResource.TRANSPORT transport = r.transport();
    if (transport != null) {
        switch (transport) {
            case WEBSOCKET:
                if (r.isComet()) {
                    r.suspend();
                }
                break;
            case COMET:
                r.suspend();
                break;
            case PULL:
            case POLLING:
            case JSONP_POLLING:
                break;
            default:
                break;
        }
    }

    return Action.CONTINUE;
}

public Action inspect(AtmosphereResource r) {
        if (r.transport() != null && r.transport() != AtmosphereResource.TRANSPORT.LONG_POLLING && r.transport() != AtmosphereResource.TRANSPORT.METEOR && !r.suspended()) {
            r.suspend();
        }
        return Action.CONTINUE;
    }

