    if (r != null) {
        switch (r.transport()) {
            case WEBSOCKET:
                r.suspend(-1, false);
                break;
            case COMET:
            case SSE:
                r.suspend(-1, false);
                break;
            case POLLING:
            case LONG_POLLING:
                break;
        }
    }
    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r) {
    if (r.transport().equals(AtmosphereResource.TRANSPORT.WEBSOCKET)) {
        if (r.suspend()) {
            return Action.CONTINUE;
        } else {
            log.severe("Unable to suspend " + r);
        }
    }
    return Action.ABORT;
}

@Override
public Action inspect(AtmosphereResource r) {
    if (r == null) {
        return Action.ABORT;
    }

    if (r.transport() == AtmosphereResource.TRANSPORT.COMET) {
        r.suspend();
    } else if (r.transport() == AtmosphereResource.TRANSPORT.LONG_POLLING) {
        r.suspend();
    } else if (r.transport() == AtmosphereResource.TRANSPORT.WEBSOCKET) {
        r.suspend();
    } else if (r.transport() == AtmosphereResource.TRANSPORT.WEBSOCKETDRAFT75 || r.transport() == AtmosphereResource.TRANSPORT.WEBSOCKETDRAFT76) {
        r.suspend();
    }
    return Action.CONTINUE;
}

