    if (aObj1 == aObj2) {
        return 0;
    }
    byte[] a = (byte[]) aObj1;
    byte[] b = (byte[]) aObj2;
    int length = Math.min(a.length, b.length);
    for (int i = 0; i < length; i++) {
        int compare = Byte.compare(a[i], b[i]);
        if (compare != 0) {
            return compare;
        }
    }
    return Integer.compare(a.length, b.length);
}

