protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.size() < 2) {
        throw new IllegalArgumentException("Invalid tour set: must contain at least 2 edges");
    }

    // Find a starting vertex
    V start = null;
    for (E edge : tour) {
        start = graph.getEdgeSource(edge);
        break;
    }

    if (start == null) {
        throw new IllegalArgumentException("No edges in tour set");
    }

    // Track visited edges to build the path
    List<E> edgePath = new ArrayList<>();
    List<V> vertexPath = new ArrayList<>();

    // Use a map from vertex to available outgoing edges in the tour
    Map<V, Set<E>> adjacency = new HashMap<>();
    for (E edge : tour) {
        V src = graph.getEdgeSource(edge);
        V dst = graph.getEdgeTarget(edge);

        // Add to adjacency for both directions? No - a tour is directed if graph is directed
        // But Graph<V,E> might be undirected. Let's handle generically:
        // We'll build a mapping from vertex to list of edges (with their other endpoint)
    }

    // Simpler approach: build a map from vertex to list of edges incident to that vertex in the tour
    Map<V, List<E>> vertexEdges = new HashMap<>();
    for (E edge : tour) {
        V src = graph.getEdgeSource(edge);
        V dst = graph.getEdgeTarget(edge);

        vertexEdges.computeIfAbsent(src, k -> new ArrayList<>()).add(edge);
        vertexEdges.computeIfAbsent(dst, k -> new ArrayList<>()).add(edge);
    }

    // Build the tour by traversing
    V current = start;
    vertexPath.add(current);

    Set<E> usedEdges = new HashSet<>();

    for (int i = 0; i < tour.size(); i++) {
        List<E> edgesFromCurrent = vertexEdges.get(current);
        if (edgesFromCurrent == null) {
            break;
        }

        E nextEdge = null;
        for (E e : edgesFromCurrent) {
            if (!usedEdges.contains(e)) {
                nextEdge = e;
                break;
            }
        }

        if (nextEdge == null) {
            break;
        }

        usedEdges.add(nextEdge);
        edgePath.add(nextEdge);

        V nextVertex;
        if (graph.getEdgeSource(nextEdge).equals(current)) {
            nextVertex = graph.getEdgeTarget(nextEdge);
        } else {
            nextVertex = graph.getEdgeSource(nextEdge);
        }

        current = nextVertex;
        vertexPath.add(current);
    }

    // Verify that we used all edges
    if (usedEdges.size() != tour.size()) {
        throw new IllegalArgumentException("Could not construct a valid tour from the given edge set");
    }

    // Verify it's a cycle (first vertex == last vertex)
    if (!vertexPath.get(0).equals(vertexPath.get(vertexPath.size() - 1))) {
        throw new IllegalArgumentException("Edge set does not form a valid cycle");
    }

    return new GraphPath<>(vertexPath, edgePath);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    // build adjacency from the tour edges only
    Map<V, Set<E>> adj = new HashMap<>();
    for (E e : tour) {
        V v = graph.getEdgeSource(e);
        W w = graph.getEdgeTarget(e);
        adj.computeIfAbsent(v, k -> new HashSet<>()).add(e);
        adj.computeIfAbsent(w, k -> new HashSet<>()).add(e);
    }

    // pick a starting vertex that has at least one incident edge in the tour
    V start = null;
    for (V v : adj.keySet()) {
        if (!adj.get(v).isEmpty()) {
            start = v;
            break;
        }
    }
    if (start == null) {
        // no edges in tour -> empty path
        return new GraphPath<>(Collections.emptyMap()); // assuming no-arg constructor or adapt accordingly
    }

    // traverse the tour to build the path
    Map<V, E> pathEdges = new HashMap<>();
    Set<E> used = new HashSet<>();
    V current = start;

    // handle cycles: loop until we return to start or run out of available edges
    while (true) {
        // find an unused edge incident to current
        E nextEdge = null;
        for (E e : adj.getOrDefault(current, Collections.emptySet())) {
            if (!used.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) break;

        // record edge on path
        pathEdges.put(current, nextEdge);
        used.add(nextEdge);

        // move to the other end of the edge
        V nextVertex = graph.getEdgeSource(nextEdge);
        if (nextVertex.equals(current)) {
            nextVertex = graph.getEdgeTarget(nextEdge);
        } else {
            nextVertex = graph.getEdgeSource(nextEdge);
        }
        current = nextVertex;

        // if we've returned to start and used all edges, stop
        if (current.equals(start) && used.size() == tour.size()) break;
    }

    return new GraphPath<>(pathEdges);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    // Get the graph's order (number of vertices)
    int order = graph.getNumVertices();

    // Create a list to hold the path of vertices
    List<V> path = new ArrayList<V>(order + 1);

    if (tour.isEmpty()) {
        // If the tour is empty, return an empty path
        return new GraphPath<V,E>(graph, path);
    }

    // Create a map to store the adjacency list of the subgraph defined by the tour
    Map<V, Queue<V>> adjacencyList = new HashMap<V, Queue<V>>();

    // Iterate through all edges in the tour
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // Add the edge to the adjacency list (bidirectional for undirected graphs)
        if (!adjacencyList.containsKey(source)) {
            adjacencyList.put(source, new LinkedList<V>());
        }
        adjacencyList.get(source).add(target);

        if (!adjacencyList.containsKey(target)) {
            adjacencyList.put(target, new LinkedList<V>());
        }
        adjacencyList.get(target).add(source);
    }

    // Find a starting vertex. In a valid tour, all vertices in the cycle should have degree 2
    V startVertex = null;
    for (V vertex : graph.getVertices()) {
        Queue<V> neighbors = adjacencyList.get(vertex);
        if (neighbors != null && neighbors.size() == 2) {
            startVertex = vertex;
            break;
        }
    }

    if (startVertex == null) {
        // If no vertex with degree 2 is found, return an empty path or handle invalid input
        // For simplicity, return an empty path
        return new GraphPath<V,E>(graph, path);
    }

    // Start adding to the path
    path.add(startVertex);
    V currentVertex = startVertex;

    // Traverse the cycle
    Set<V> visited = new HashSet<V>();
    visited.add(startVertex);

    boolean completedCycle = false;
    while (visited.size() < order && !completedCycle) {
        Queue<V> neighbors = adjacencyList.get(currentVertex);
        if (neighbors != null) {
            V nextVertex = null;
            while (!neighbors.isEmpty()) {
                V potentialNext = neighbors.poll();
                if (!visited.contains(potentialNext)) {
                    nextVertex = potentialNext;
                    break;
                } else if (potentialNext.equals(startVertex) && visited.size() >= 2) {
                    // We have returned to the start vertex, completing the cycle
                    completedCycle = true;
                    break;
                }
            }
            if (nextVertex != null) {
                path.add(nextVertex);
                visited.add(nextVertex);
                currentVertex = nextVertex;
            } else if (neighbors.isEmpty()) {
                // No more unvisited neighbors and no cycle completion
                break;
            }
        } else {
            break;
        }
    }

    return new GraphPath<V,E>(graph, path);
}

