private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffixSums = new ArrayList<>();
    long totalSum = 0;
    for (int bound : bounds) {
        totalSum += bound;
    }
    long suffixSum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        suffixSum += bounds.get(i);
        suffixSums.add((int) suffixSum);
    }
    Collections.reverse(suffixSums);
    return Pair.of(suffixSums, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSums = new ArrayList<>();
    long sum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSums.add((int) sum);
    }
    Collections.reverse(suffixSums);
    return new Pair<>(suffixSums, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSums = new ArrayList<>();
    long totalSum = 0L;
    long runningSum = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        int bound = bounds.get(i);
        runningSum += bound;
        totalSum += bound;
        suffixSums.add(0, (int) runningSum);
    }
    return new Pair<>(suffixSums, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || from < 0 || to >= arr.length || from > to) {
        return;
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
        assert list != this;
        if (list == null || list.head == null) {
            return;
        }
        ListNodeImpl<E> first = list.head;
        ListNodeImpl<E> last = list.tail;
        // detach list from its own structure
        list.head = null;
        list.tail = null;
        list.size = 0;
        // attach to this list
        if (head == null) {
            head = first;
            tail = last;
        } else {
            last.next = head;
            head.prev = last;
            tail.next = first;
            first.prev = tail;
        }
        size += list.size;
        last.next = first;
        first.prev = last;
    }

private void moveAllListNodes(DoublyLinkedList<E> list) {
    ListNode<E> node = list.head;
    while (node != null) {
        ListNode<E> next = node.next;
        // Detach the node from its current list
        list.detach(node);
        // Add the node to this list
        this.addLast(node);
        node = next;
    }
    list.clear();
}

