private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();
    for (E e : graph.edges()) {
        List<Integer> neighbors = new ArrayList<>();
        for (V v : graph.vertices()) {
            if (graph.hasEdge(v, e)) {
                for (Edge incidentEdge : graph.incidentEdges()) {
                    if (incidentEdge.incidentTo(v) && incidentEdge != e) {
                        V otherVertex = incidentEdge.opposite(v);
                        Integer label = graph.getLabel(otherVertex);
                        neighbors.add(label);
                    }
                }
            }
        }
        neighbors = neighbors.stream().distinct().collect(Collectors.toList());
        List<Pair<Integer, Integer>> edgePairs = new ArrayList<>();
        for (int i = 0; i < neighbors.size(); i++) {
            for (int j = i + 1; j < neighbors.size(); j++) {
                edgePairs.add(new Pair<>(neighbors.get(i), neighbors.get(j)));
            }
        }
        List<List<Pair<Integer, Integer>>> minimalSeparators = getMinimalSeparators(e, edgePairs);
        for (List<Pair<Integer, Integer>> separator : minimalSeparators) {
            globalSeparatorList.add(new Pair<>(separator, e));
        }
    }
    return globalSeparatorList;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
        List<Pair<List<Pair<Integer,Integer>>,E>> result = new ArrayList<>();
        for (E edge : graph.edgeSet()) {
            result.addAll(computeMinimalSeparators(edge));
        }
        return result;
    }

