        if (bounds == null || bounds.length <= 1) {
            return Unknown.class;
        } else {
            return bounds[0];
        }
    } else {
        Map<TypeVariable<?>, Type> typeVariableMap = getTypeVariableMap();
        Type type = typeVariableMap.get(typeVariable);
        if (type != null) {
            return type;
