public static String applyRelativePath(String path, String relativePath) {
    if (path == null || path.isEmpty()) {
        return relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    // Standardize separators to slashes if needed, though the spec says assume "/"
    // Let's ensure path ends with a separator if relative path is relative (does not start with /)
    // If relativePath starts with /, it's an absolute path (or root-relative), usually just return it or handle based on specific requirements.
    // The description says "relative path to apply (relative to the full file path above)".
    // Usually, applying a relative path means: path + "/" + relativePath, or path + relativePath if path already ends with /

    // However, true relative paths can include ".." or ".".
    // Example: path = "/a/b", relativePath = "../c" -> "/a/c"
    // Example: path = "/a/b", relativePath = "c" -> "/a/b/c"

    // Let's implement a simple resolver.
    List<String> pathParts = new ArrayList<String>();
    String[] parts = path.split("/");
    for (String part : parts) {
        if (part.equals("..")) {
            if (!pathParts.isEmpty()) {
                pathParts.remove(pathParts.size() - 1);
            }
        } else if (!part.equals(".") && !part.isEmpty()) {
            pathParts.add(part);
        }
    }

    if (relativePath.startsWith("/")) {
        // Absolute path, ignore the starting path
        pathParts.clear();
    }

    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.equals("..")) {
            if (!pathParts.isEmpty()) {
                pathParts.remove(pathParts.size() - 1);
            }
        } else if (!part.equals(".") && !part.isEmpty()) {
            pathParts.add(part);
        }
    }

    // Reconstruct
    if (pathParts.isEmpty()) {
        return "/";
    }

    String result = "/" + String.join("/", pathParts);

    // Preserve trailing slash if original path ended with slash?
    // The standard Java split discards empty trailing strings.
    // Example: path = "/foo/", relativePath = ""
    // split("/") -> ["", "foo"] -> pathParts: ["foo"] -> result "/foo"
    // But "/foo/" is different from "/foo" in terms of directory vs file?
    // Usually applyRelativePath results in a valid path.
    // Let's check if input path ended with a slash and relative path is empty.
    // If original path ends with / and relativePath is empty, should return original path?

    return result.endsWith("/") || path.endsWith("/") && relativePath.isEmpty() ? (result.equals("/") ? "/" : result + "/") : result;
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        throw new IllegalArgumentException("Path cannot be null");
    }
    if (relativePath == null) {
        throw new IllegalArgumentException("Relative path cannot be null");
    }

    // Normalize path to use '/' separators
    String normalizedPath = path.replace('\\', '/');

    // Handle edge cases
    if (relativePath.isEmpty()) {
        return normalizedPath;
    }

    // If relative path is just a filename (no slash), append it to path
    if (!relativePath.contains("/")) {
        if (normalizedPath.endsWith("/")) {
            return normalizedPath + relativePath;
        }
        return normalizedPath + "/" + relativePath;
    }

    // Process relative path components
    String[] parts = relativePath.split("/");
    String[] pathParts = normalizedPath.split("/");
    int pathIndex = pathParts.length;
    int relIndex = 0;

    // Remove last component of path (it's the file being replaced)
    // Actually, we want to apply the relative path to the directory part
    // The standard interpretation: path is the base directory, relativePath is relative to it
    // But looking at the examples, it seems like we're combining paths

    // Let's build the result by combining path and relativePath, handling ".." and "."
    List<String> result = new ArrayList<>();

    // Add all path components
    for (String part : pathParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!result.isEmpty()) {
                result.remove(result.size() - 1);
            }
        } else {
            result.add(part);
        }
    }

    // Add relative path components
    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!result.isEmpty()) {
                result.remove(result.size() - 1);
            }
        } else {
            result.add(part);
        }
    }

    // Reconstruct the path
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < result.size(); i++) {
        if (i > 0) {
            sb.append("/");
        }
        sb.append(result.get(i));
    }

    String resultStr = sb.toString();

    // Preserve leading slash if original path had one
    if (normalizedPath.startsWith("/") && !resultStr.startsWith("/")) {
        resultStr = "/" + resultStr;
    }

    return resultStr;
}

