        return new String[0];
    }
    int count = 0;
    for (Object element : array) {
        if (element != null) {
            count++;
        }
    }
    String[] result = new String[count];
    int index = 0;
    for (Object element : array) {
        if (element != null) {
            if (element instanceof String) {
                result[index++] = (String) element;
            } else {
                result[index++] = element.toString();
            }
        }
    }
    return result;
}

