public boolean isExpired(long timestamp, long expiredThreshold) {
    // If no threshold is specified, assume the entry is never expired.
    if (expiredThreshold < 0) {
        return false;
    }

    // Check if the current time exceeds the update time by the threshold duration.
    // Using Long.MAX_VALUE prevents overflow.
    // Time to live has elapsed if (currentTime - updateTime) > threshold.
    // This is equivalent to currentTime > updateTime + threshold.
    // To handle overflow, we can rearrange if updateTime > 0: 
    // currentTime - updateTime > threshold 
    // Or simply check if currentTime exceeds updateTime + threshold, handling overflow.

    // Another robust way: check if (timestamp > updateTime) && (timestamp - updateTime > expiredThreshold)
    if (timestamp <= updateTime) {
        return false;
    }

    return (timestamp - updateTime) > expiredThreshold;
}

