    if (this.node == null) {
        throw new IllegalStateException("No current node available.");
    }
    Edge edge = this.currentEdge;
    if (edge == null) {
        return null;
    }

    Node nextNode;
    if (this.hasNext()) {
        nextNode = this.next();
    } else {
        return null;
    }

    if (this.node.isVirtual()) {
        this.node = this.realNode();
    }
    if (nextNode.isVirtual()) {
        nextNode = this.realNode(nextNode);
    }

    return edge;
}

