private void checkIfPackedField() throws IOException {
    if (fieldDescriptor.isPacked() && fieldDescriptor.isSingular()) {
        // Start reading the length
        buffer = ArrayBlockingQueue.ofSize(1);
        int length = readRawVarint32();
        if (length < 0) {
            throw new IllegalArgumentException("Negative length for packed field: " + fieldDescriptor.getFullName());
        }
        // Set the end position for the packed field
        limit = position + length;
        // Read each element until the limit is reached
        while (position < limit) {
            if (fieldDescriptor.getJavaType().equals(Type.INT32)) {
                target.addValue(readInt());
            } else if (fieldDescriptor.getJavaType().equals(Type.INT64)) {
                target.addValue(readLong());
            } else if (fieldDescriptor.getJavaType().equals(Type.UINT32)) {
                target.addValue(readUInt32());
            } else if (fieldDescriptor.getJavaType().equals(Type.UINT64)) {
                target.addValue(readUInt64());
            } else if (fieldDescriptor.getJavaType().equals(Type.FLOAT)) {
                target.addValue(readFloat());
            } else if (fieldDescriptor.getJavaType().equals(Type.DOUBLE)) {
                target.addValue(readDouble());
            } else if (fieldDescriptor.getJavaType().equals(Type.BOOL)) {
                target.addValue(readBool());
            } else {
                throw new UnsupportedOperationException(
                        "Packed field not supported for this type: " + fieldDescriptor.getJavaType());
            }
        }
    }
}

