        for (ThreadSnapshot snapshot : allSnapshots) {
            long timestamp = snapshot.getTimestamp();
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                long start = timeRange.getStart();
                long end = timeRange.getEnd();
                if (timestamp >= start && timestamp <= end) {
                    result.add(snapshot);
                    break;
                }
            }
        }
    }
    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    List<ThreadSnapshot> allSnapshots = ProfilingUtils.parseFromFile(file);
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        long startTime = timeRange.getStartTime();
        long endTime = timeRange.getEndTime();
        for (ThreadSnapshot snapshot : allSnapshots) {
            if (snapshot.getTimestamp() >= startTime && snapshot.getTimestamp() <= endTime) {
                result.add(snapshot);
            }
        }
    }
    return result;
}

static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        String fieldName = null;
        ProfileAnalyzeTimeRange currentRange = null;
        ThreadSnapshot currentSnapshot = null;
        Map<Long, List<ThreadSnapshot>> snapshotsByTime = new HashMap<>();
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            if (line.startsWith("#")) {
                // Check if it's a time range marker
                if (line.contains("=")) {
                    String[] parts = line.split("=", 2);
                    fieldName = parts[0].trim().substring(1); // remove #
                    String value = parts[1].trim();
                    if ("TIME_RANGE".equals(fieldName)) {
                        // parse time range from value
                        if (currentRange != null) {
                            // save previous range's snapshots
                            if (currentSnapshot != null) {
                                if (snapshotsByTime.containsKey(currentSnapshot.getStartTime())) {
                                    snapshotsByTime.get(currentSnapshot.getStartTime()).add(currentSnapshot);
                                } else {
                                    List<ThreadSnapshot> list = new ArrayList<>();
                                    list.add(currentSnapshot);
                                    snapshotsByTime.put(currentSnapshot.getStartTime(), list);
                                }
                                currentSnapshot = null;
                            }
                        }
                        // create new range or reuse logic if multiple ranges
                        // For simplicity, assume one snapshot per line after header
                        try {
                            currentRange = new ProfileAnalyzeTimeRange();
                            // Assume value is like "start:end"
                            String[] times = value.split(":");
                            if (times.length == 2) {
                                currentRange.setStartTime(Long.parseLong(times[0]));
                                currentRange.setEndTime(Long.parseLong(times[1]));
                            }
                        } catch (Exception e) {
                            // ignore parse errors for time range
                        }
                        fieldName = null;
                    } else if ("START_TIME".equals(fieldName)) {
                        if (currentSnapshot != null) {
                            currentSnapshot = null; // reset?
                        }
                        try {
                            long startTime = Long.parseLong(value);
                            currentSnapshot = new ThreadSnapshot();
                            currentSnapshot.setStartTime(startTime);
                        } catch (NumberFormatException e) {
                            // ignore
                        }
                        fieldName = null;
                    } else if ("THREAD_ID".equals(fieldName)) {
                        if (currentSnapshot != null) {
                            try {
                                currentSnapshot.setThreadId(Long.parseLong(value));
                            } catch (NumberFormatException e) {
                                // ignore
                            }
                        }
                        fieldName = null;
                    } else if ("THREAD_NAME".equals(fieldName)) {
                        if (currentSnapshot != null) {
                            currentSnapshot.setThreadName(value);
                        }
                        fieldName = null;
                    } else if ("STATE".equals(fieldName)) {
                        if (currentSnapshot != null) {
                            currentSnapshot.setState(value);
                        }
                        fieldName = null;
                    } else if ("STACK_TRACE".equals(fieldName)) {
                        // We don't have a place to put stack trace easily, ignore for now
                        fieldName = null;
                    }
                } else {
                    fieldName = null;
                }
            } else {
                // It's a data line assuming format: timeRangeStart|threadId|threadName|state|stacktrace
                // But from previous logic, we were reading key=value? Let's assume a simpler CSV-like or key=val format is hardcoded.
                // Given the ambiguity without exact format spec, I will assume the standard JFR-like or custom line format.
                // Let's assume lines are: startTime|endTime|threadId|threadName|state
                // Or maybe the file format is defined elsewhere. 

                // Let's try a common guess: Lines starting with a number
                if (line.matches("^\\d+.*$")) {
                    String[] parts = line.split("\\|");
                    if (parts.length >= 5) {
                        long startTime = Long.parseLong(parts[0]);
                        long endTime = Long.parseLong(parts[1]);
                        long threadId = Long.parseLong(parts[2]);
                        String threadName = parts[3];
                        String state = parts[4];

                        ThreadSnapshot ts = new ThreadSnapshot();
                        ts.setStartTime(startTime);
                        ts.setThreadId(threadId);
                        ts.setThreadName(threadName);
                        ts.setState(state);

                        // Check if in any time range
                        for (ProfileAnalyzeTimeRange range : timeRanges) {
                            if (startTime >= range.getStartTime() && startTime <= range.getEndTime()) {
                                result.add(ts);
                                break;
                            }
                        }
                    }
                }
            }
        }
    }
    return result;
}
